// retry.ts
export type Sleeper = (ms: number) => Promise<void>;
export type RandomSource = () => number;
export type JitterStrategy = "full" | "half" | "none";

export interface RetryOptions {
  /** Maximum number of attempts (including the first). */
  attempts: number;
  /** Delay before the first retry, in milliseconds. */
  baseDelayMs: number;
  /** Multiplier applied to the delay after each retry. Defaults to 2. */
  factor?: number;
  /** Upper bound on any computed delay. Defaults to Infinity. */
  maxDelayMs?: number;
  /** Jitter strategy. Defaults to "full". */
  jitter?: JitterStrategy;
  /** Aborts retries when signaled. */
  signal?: AbortSignal;
  /** Injected sleeper. Defaults to a real setTimeout-based sleep. */
  sleep?: Sleeper;
  /** Injected random source in [0, 1). Defaults to Math.random. */
  random?: RandomSource;
  /** Decides whether an error is retryable. Defaults to retrying everything. */
  isRetryable?: (error: unknown) => boolean;
}

export class RetryError extends Error {
  constructor(
    message: string,
    public readonly attempts: number,
    public readonly cause: unknown
  ) {
    super(message);
    this.name = "RetryError";
  }
}

export const defaultSleep: Sleeper = (ms: number) =>
  new Promise((resolve) => setTimeout(resolve, ms));

const defaultRandom: RandomSource = () => Math.random();

const defaultIsRetryable = (): boolean => true;

export function computeDelay(
  attempt: number, // 0-based: delay before retry #1
  opts: Required<
    Pick<RetryOptions, "baseDelayMs" | "factor" | "maxDelayMs" | "jitter" | "random">
  >
): number {
  let raw = opts.baseDelayMs * Math.pow(opts.factor, attempt);
  if (!Number.isFinite(raw) || raw > opts.maxDelayMs) {
    raw = opts.maxDelayMs;
  }
  const r = opts.random();
  switch (opts.jitter) {
    case "full":
      return raw * r;
    case "half":
      return raw * (0.5 + 0.5 * r);
    case "none":
      return raw;
  }
}

export async function retry<T>(
  fn: (attempt: number) => Promise<T>,
  options: RetryOptions
): Promise<T> {
  const attempts = options.attempts;
  if (!Number.isInteger(attempts) || attempts < 1) {
    throw new RangeError("attempts must be an integer >= 1");
  }

  const sleep = options.sleep ?? defaultSleep;
  const random = options.random ?? defaultRandom;
  const isRetryable = options.isRetryable ?? defaultIsRetryable;
  const factor = options.factor ?? 2;
  const maxDelayMs = options.maxDelayMs ?? Infinity;
  const jitter = options.jitter ?? "full";

  const signal = options.signal;

  const throwIfAborted = (): void => {
    if (signal?.aborted) {
      throw signal.reason ?? new DOMException("Aborted", "AbortError");
    }
  };

  let lastError: unknown;
  for (let attempt = 0; attempt < attempts; attempt++) {
    throwIfAborted();

    try {
      return await fn(attempt);
    } catch (error) {
      lastError = error;

      if (attempt === attempts - 1) break;
      if (!isRetryable(error)) break;

      const delay = computeDelay(attempt, {
        baseDelayMs: options.baseDelayMs,
        factor,
        maxDelayMs,
        jitter,
        random,
      });

      throwIfAborted();

      if (signal) {
        await abortableSleep(delay, sleep, signal);
      } else {
        await sleep(delay);
      }
    }
  }

  throwIfAborted();
  throw new RetryError(
    `retry: all ${attempts} attempts failed`,
    attempts,
    lastError
  );
}

async function abortableSleep(
  ms: number,
  sleep: Sleeper,
  signal: AbortSignal
): Promise<void> {
  if (signal.aborted) {
    throw signal.reason ?? new DOMException("Aborted", "AbortError");
  }
  await new Promise<void>((resolve, reject) => {
    const onAbort = () => {
      cleanup();
      reject(signal.reason ?? new DOMException("Aborted", "AbortError"));
    };
    const onDone = () => {
      cleanup();
      resolve();
    };
    const cleanup = () => {
      signal.removeEventListener("abort", onAbort);
